<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch, watchEffect } from 'vue';
import { ElButton, ElCard } from 'element-plus';
import type { Context, Role, Scenario } from './dashboard';
import { devices, type Device } from './devices';
import { firmwares, inspectFirmwareFile, type FileInspection, type Firmware, type FirmwareInput, type FirmwareQuery } from './firmware';
import { ota, type FailureMode, type OtaInput, type OtaPreview, type OtaQuery, type OtaTask } from './ota';
import { otaTrend, otaTrendPath } from './ota-trend';
import { otaVersionDistribution } from './ota-version';
import { tenants as tenantService } from './tenants';
import './dashboard.css';
import './products.css';
import './firmware-ota.css';

type Action = 'verify' | 'release' | 'archive' | 'remove' | 'start' | 'pause' | 'resume' | 'cancel' | 'retry' | 'rollback';
const tenants = [{ id: 'all', name: '全部租户' }, { id: 'ten_202609_001', name: '华东智联' }, { id: 'ten_202609_002', name: '全球能源' }];
const productNames: Record<string, string> = { prod_as_001: '工业温湿度传感器', prod_as_002: '能源网关' };
const firmwareStatus: Record<Firmware['status'], string> = { draft: '草稿', verified: '已校验', released: '已发布', archived: '已归档' };
const taskStatus: Record<OtaTask['status'], string> = { draft: '草稿', queued: '等待', downloading: '下载', verifying: '校验', installing: '安装', rebooting: '重启', paused: '已暂停', succeeded: '成功', failed: '失败', cancelled: '已取消', rollingBack: '回滚中', rolledBack: '已回滚' };
const otaActionLabels: Record<Action, string> = { verify: '校验', release: '发布', archive: '归档', remove: '删除', start: '开始', pause: '暂停', resume: '继续', cancel: '取消', retry: '重试', rollback: '回滚' };
const fBase = (tenantId = localStorage.getItem('iot-atlas-current-tenant-v1') || 'all'): FirmwareQuery => ({ tenantId, seed: 42, page: 1, pageSize: 10 });
const oBase = (tenantId = localStorage.getItem('iot-atlas-current-tenant-v1') || 'all'): OtaQuery => ({ tenantId, seed: 42, page: 1, pageSize: 10 });
const emptyFirmware = (tenantId: string): Omit<FirmwareInput, keyof FileInspection> => ({ tenantId, productId: tenantId === 'ten_202609_002' ? 'prod_as_002' : 'prod_as_001', compatibleProductIds: [tenantId === 'ten_202609_002' ? 'prod_as_002' : 'prod_as_001'], name: '', version: '', description: '' });
const emptyOta = (tenantId: string): OtaInput => ({ tenantId, firmwareId: '', productId: tenantId === 'ten_202609_002' ? 'prod_as_002' : 'prod_as_001', targetSelector: { deviceIds: [], tags: [] }, batches: [10, 30, 60], failureThreshold: 0.2, failureModes: {} });
const plain = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const displayTime = (value: string) => new Date(value).toLocaleString('zh-CN');
const finished = (status: OtaTask['status']) => ['draft', 'paused', 'succeeded', 'failed', 'cancelled', 'rolledBack'].includes(status);
const tab = ref<'firmware' | 'ota'>(new URLSearchParams(location.search).get('tab') === 'ota' ? 'ota' : 'firmware');
const role = ref<Role>('platformAdmin'), scenario = ref<Scenario>('normal');
const themeChoice = ref(localStorage.getItem('iot-atlas-theme') || 'dark'), systemDark = ref(matchMedia('(prefers-color-scheme: dark)').matches);
const dark = computed(() => themeChoice.value === 'dark' || (themeChoice.value === 'system' && systemDark.value));
const canManage = computed(() => role.value === 'platformAdmin' || role.value === 'tenantAdmin');
const canOperate = computed(() => role.value !== 'viewer');
const message = ref('');
const fDraftFilter = ref<FirmwareQuery>(fBase()), fFilter = ref<FirmwareQuery>(fBase()), fRows = ref<Firmware[]>([]), fTotal = ref(0);
const selectedFirmware = ref<(Firmware & { referencedTaskIds: string[] }) | null>(null), fStep = ref(0), fileState = ref<'idle' | 'reading' | 'ready'>('idle'), fileProgress = ref(0), fileInfo = ref<FileInspection | null>(null), fInput = ref(emptyFirmware('ten_202609_001'));
const storageNote = ref('');
const versionPeers = ref<Firmware[]>([]);
const oDraftFilter = ref<OtaQuery>(oBase()), oFilter = ref<OtaQuery>(oBase()), oRows = ref<OtaTask[]>([]), oTotal = ref(0);
const task = ref<OtaTask | null>(null), oStep = ref(0), oInput = ref<OtaInput>(emptyOta('ten_202609_001')), preview = ref<OtaPreview | null>(null), options = ref<Firmware[]>([]), targets = ref<Device[]>([]), connected = ref(true);
const capacityNote = ref('');
const confirm = ref<{ action: Action; deviceId?: string } | null>(null), deviceFilter = ref<'all' | 'failed' | 'succeeded'>('all'), reasonFilter = ref(''), revision = ref(0);
const context = (): Context => ({ actorId: 'usr_202609_001', role: role.value, tenantId: role.value === 'platformAdmin' ? 'all' : 'ten_202609_001', seed: 42, scenario: scenario.value });
watch([fStep, fileInfo, () => fInput.value.tenantId, role, scenario], async ([step, file, tenantId], _, onCleanup) => {
  if (step !== 3 || !file) { storageNote.value = ''; return; }
  let active = true; onCleanup(() => { active = false; }); storageNote.value = '正在查询存储配额…';
  const result = await firmwares.previewStorage(context(), tenantId, file.sizeBytes);
  if (!active) return;
  if ('error' in result) { storageNote.value = result.error.message; return; }
  const { used, projected, limit, warningAt } = result.data;
  storageNote.value = `存储已用 ${used}/${limit} MiB；登记后预计 ${projected}/${limit} MiB${projected > limit ? '，将超过上限' : projected / limit * 100 >= warningAt ? `，达到 ${warningAt}% 预警阈值` : ''}`;
});
watch([() => task.value?.tenantId, () => task.value?.status, role, scenario], async ([tenantId, status], _, onCleanup) => {
  if (!tenantId || !['draft', 'paused'].includes(status ?? '') || role.value === 'viewer') { capacityNote.value = ''; return; }
  let active = true; onCleanup(() => { active = false; }); capacityNote.value = '正在查询 OTA 并发配额…';
  const quotaContext = role.value === 'operator' ? { ...context(), role: 'tenantAdmin' as const } : context();
  const result = await tenantService.checkCapacity(quotaContext, tenantId, 'otaConcurrent');
  if (!active) return;
  const action = status === 'paused' ? '继续' : '启动';
  capacityNote.value = 'error' in result ? result.error.message : `OTA 并发已用 ${result.data.used}/${result.data.limit}${(result.data.used + 1) / result.data.limit * 100 >= result.data.warningAt ? `；${action}后达到 ${result.data.warningAt}% 预警阈值` : ''}`;
});
const media = matchMedia('(prefers-color-scheme: dark)');
const mediaChanged = () => { systemDark.value = media.matches; };
watch(dark, value => { document.documentElement.dataset.theme = value ? 'dark' : 'light'; localStorage.setItem('iot-atlas-theme', themeChoice.value); }, { immediate: true });
onMounted(() => { media.addEventListener('change', mediaChanged); const id = new URLSearchParams(location.search).get('task'); if (id) void openTask(id); });
onBeforeUnmount(() => media.removeEventListener('change', mediaChanged));
async function loadFirmware() { const result = await firmwares.list(context(), fFilter.value); if ('error' in result) message.value = result.error.message; else { fRows.value = result.data.items; fTotal.value = result.data.total; } }
async function loadOta() { const result = await ota.list(context(), oFilter.value); if ('error' in result) message.value = result.error.message; else { oRows.value = result.data.items; oTotal.value = result.data.total; } }
watch([fFilter, role, scenario, revision], () => void loadFirmware(), { immediate: true });
watch([oFilter, role, scenario, revision], () => void loadOta(), { immediate: true });
watchEffect(onCleanup => { const id = task.value?.id, status = task.value?.status; if (!id || !status || !connected.value || finished(status)) return; let live = true, busy = false; const timer = setInterval(async () => { if (busy) return; busy = true; const result = await ota.advance(context(), id); if (live) { if ('error' in result) { message.value = result.error.message; connected.value = false; } else { task.value = result.data; revision.value++; } } busy = false; }, 900); onCleanup(() => { live = false; clearInterval(timer); }); });
const latest = computed(() => task.value ? [...new Map(task.value.executions.map(item => [item.deviceId, item])).values()] : []);
const taskTrend = computed(() => task.value ? otaTrend(task.value) : []);
const done = computed(() => latest.value.filter(item => item.status === 'succeeded').length);
const failed = computed(() => latest.value.filter(item => item.status === 'failed').length);
const progress = computed(() => task.value ? Math.round((done.value + failed.value) / task.value.targetSelector.deviceIds.length * 100) : 0);
const filteredExecutions = computed(() => task.value?.executions.filter(item => (deviceFilter.value === 'all' || item.status === deviceFilter.value) && (!reasonFilter.value || item.reason?.includes(reasonFilter.value))) ?? []);
const confirmationText = computed(() => { if (!confirm.value) return ''; const texts: Record<Action, string> = { verify: '验证固件 SHA-256 元数据。', release: '发布后可被 OTA 任务选择，正式版本不可覆盖。', archive: '归档后不可创建新的 OTA。', remove: '删除固件元数据；引用任务仍存在时会被阻止。', start: `开始影响 ${task.value?.targetSelector.deviceIds.length ?? 0} 台设备的升级。`, pause: '暂停当前任务，设备进度暂不推进。', resume: '继续任务并可能启动下一灰度批次。', cancel: '取消任务并保留已产生的记录。', retry: `重试设备 ${confirm.value.deviceId ?? ''}，保留原失败尝试。`, rollback: `将 ${done.value} 台成功设备恢复到原版本，并新建反向升级任务。` }; return texts[confirm.value.action]; });
function setRole(next: Role) { role.value = next; const id = next === 'platformAdmin' ? 'all' : 'ten_202609_001'; fDraftFilter.value = fBase(id); fFilter.value = fBase(id); oDraftFilter.value = oBase(id); oFilter.value = oBase(id); selectedFirmware.value = null; task.value = null; fStep.value = 0; oStep.value = 0; message.value = ''; }
async function openFirmware(id: string) { const result = await firmwares.get(context(), id); if ('error' in result) { message.value = result.error.message; return; } selectedFirmware.value = result.data; fStep.value = 0; const peers = await firmwares.list(context(), { tenantId: result.data.tenantId, productId: result.data.productId, seed: 42, page: 1, pageSize: 100 }); if ('data' in peers) versionPeers.value = peers.data.items; else message.value = peers.error.message; }
function newFirmware() { selectedFirmware.value = null; fInput.value = emptyFirmware(fFilter.value.tenantId === 'all' ? 'ten_202609_001' : fFilter.value.tenantId); fileInfo.value = null; fileState.value = 'idle'; fStep.value = 1; message.value = ''; }
let fileReadToken = 0;
function cancelFile() { fileReadToken++; fileInfo.value = null; fileProgress.value = 0; fileState.value = 'idle'; fStep.value = 0; }
async function selectFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; const token = ++fileReadToken; fileState.value = 'reading'; fileProgress.value = 0; fileInfo.value = null; const result = await inspectFirmwareFile(file, percent => { if (token === fileReadToken) fileProgress.value = percent; }); if (token !== fileReadToken) return; if ('error' in result) { message.value = result.error.message; fileState.value = 'idle'; fileProgress.value = 0; return; } fileInfo.value = result; fileProgress.value = 100; fileState.value = 'ready'; message.value = 'SHA-256 校验完成，文件内容仅用于本次读取'; }
async function saveFirmware() { if (!fileInfo.value) return; const result = await firmwares.create(context(), { ...plain(fInput.value), ...plain(fileInfo.value) }); if ('error' in result) { message.value = result.error.message; return; } fStep.value = 0; revision.value++; message.value = '固件元数据已登记为草稿，请验证并发布'; await openFirmware(result.data.id); }
async function newOta() { const id = oFilter.value.tenantId === 'all' ? 'ten_202609_001' : oFilter.value.tenantId; task.value = null; oInput.value = emptyOta(id); preview.value = null; oStep.value = 1; message.value = ''; await loadFirmwareOptions(id); }
async function loadFirmwareOptions(id: string) { const result = await firmwares.list(context(), { tenantId: id, seed: 42, page: 1, pageSize: 100 }); if ('data' in result) options.value = result.data.items.filter(row => row.status === 'released' && row.checksumValid); else message.value = result.error.message; }
async function chooseFirmware(id: string) { const row = options.value.find(item => item.id === id); oInput.value = { ...oInput.value, firmwareId: id, productId: row?.productId ?? oInput.value.productId, targetSelector: { deviceIds: [], tags: [] } }; if (row) { const result = await devices.list(context(), { tenantId: row.tenantId, seed: 42, productId: row.productId, page: 1, pageSize: 100 }); if ('data' in result) targets.value = result.data.items; else message.value = result.error.message; } }
function target(id: string, checked: boolean) { oInput.value = { ...oInput.value, targetSelector: { ...oInput.value.targetSelector, deviceIds: checked ? [...oInput.value.targetSelector.deviceIds, id] : oInput.value.targetSelector.deviceIds.filter(item => item !== id) } }; }
async function previewOta() { const result = await ota.preview(context(), plain(oInput.value)); if ('error' in result) { message.value = result.error.message; return; } preview.value = result.data; oStep.value = 4; message.value = '影响预览已生成；请核对目标和失败阈值'; }
async function createOta() { const result = await ota.create(context(), plain(oInput.value)); if ('error' in result) { message.value = result.error.message; return; } task.value = result.data; oStep.value = 0; tab.value = 'ota'; revision.value++; message.value = 'OTA 草稿已创建；确认后开始模拟'; }
async function openTask(id: string) { const result = await ota.get(context(), id); if ('error' in result) message.value = result.error.message; else { task.value = result.data; oStep.value = 0; connected.value = true; tab.value = 'ota'; } }
async function runAction() { if (!confirm.value) return; const action = confirm.value.action, deviceId = confirm.value.deviceId; confirm.value = null;
  if (['verify', 'release', 'archive', 'remove'].includes(action) && selectedFirmware.value) { const row = selectedFirmware.value; const result = action === 'remove' ? await firmwares.remove(context(), row.id, row.revision) : await firmwares.transition(context(), row.id, action as 'verify' | 'release' | 'archive', row.revision); if ('error' in result) { message.value = result.error.message; return; } if (action === 'remove') selectedFirmware.value = null; else await openFirmware(row.id); message.value = `固件操作已完成：${action}`; }
  else if (task.value) { const id = task.value.id, version = task.value.revision; const result = action === 'start' ? await ota.start(context(), id, version) : action === 'pause' ? await ota.pause(context(), id, version) : action === 'resume' ? await ota.resume(context(), id, version) : action === 'cancel' ? await ota.cancel(context(), id, version) : action === 'retry' ? await ota.retry(context(), id, deviceId ?? '', version) : await ota.rollback(context(), id, version); if ('error' in result) { message.value = result.error.message; return; } task.value = result.data; connected.value = true; message.value = action === 'rollback' ? `已创建独立回滚任务 ${result.data.id}，原任务历史保留` : `OTA 操作已完成：${otaActionLabels[action]}`; }
  revision.value++;
}
async function manualAdvance() { if (!task.value) return; const result = await ota.advance(context(), task.value.id); if ('data' in result) { task.value = result.data; revision.value++; } else message.value = result.error.message; }
function setNewTenant(id: string) { fInput.value = emptyFirmware(id); }
function setOtaTenant(id: string) { oInput.value = emptyOta(id); void loadFirmwareOptions(id); }
function setOtaTags(value: string) { oInput.value = { ...oInput.value, targetSelector: { ...oInput.value.targetSelector, tags: value.split(',').map(item => item.trim()).filter(Boolean) } }; }
function setFailureDevice(id: string) { oInput.value = { ...oInput.value, failureModes: id ? { [id]: 'download' } : {} }; }
function setFailureMode(mode: FailureMode) { const id = Object.keys(oInput.value.failureModes)[0]; if (id) oInput.value = { ...oInput.value, failureModes: { [id]: mode } }; }
</script>
<template>
<div class="atlas-dashboard atlas-firmware"><aside class="atlas-sidebar" aria-label="主导航"><div class="atlas-brand">IoT <strong>Atlas</strong></div><nav><a href="/dashboard">◇ 数据大盘</a><a href="/geography">◇ 全球节点</a><a href="/products">◇ 产品与物模型</a><a href="/devices">◇ 设备中心</a><a href="/rules">◇ 规则引擎</a><a class="active" aria-current="page" href="/firmware">▣ 固件与 OTA</a><a href="/tenants">◇ 租户管理</a><a href="/labs">◇ 实验室</a><a href="/delivery">◇ 交付看板</a></nav><a class="diagnostic-link" href="/">诊断页</a></aside>
<main class="atlas-workspace"><header class="atlas-header"><div><small>IoT Atlas / 设备中心 / 固件与 OTA</small><h1>固件与 OTA</h1><p>登记固件元数据，按批次模拟升级与回滚。</p></div><div class="header-actions"><label>主题<select aria-label="主题" v-model="themeChoice"><option value="dark">暗色</option><option value="light">亮色</option><option value="system">跟随系统</option></select></label><label>演示身份<select aria-label="演示身份" :value="role" @change="setRole(($event.target as HTMLSelectElement).value as Role)"><option value="platformAdmin">平台管理员</option><option value="tenantAdmin">租户管理员</option><option value="operator">运维工程师</option><option value="viewer">数据观察员</option></select></label></div></header>
<nav class="firmware-tabs" aria-label="固件与 OTA 页面"><button :aria-current="tab === 'firmware' ? 'page' : undefined" @click="tab = 'firmware'">固件管理</button><button :aria-current="tab === 'ota' ? 'page' : undefined" @click="tab = 'ota'">OTA 任务</button></nav>
<div class="dashboard-feedback" aria-live="polite"><span v-if="message" role="status">{{ message }}</span><details class="scenario-control"><summary>Mock 场景</summary><label>服务状态<select aria-label="固件 OTA Mock 场景" v-model="scenario"><option value="normal">正常</option><option value="slow">缓慢</option><option value="offline">服务离线</option><option value="forbidden">无权限</option></select></label></details></div>
<div v-if="tab === 'firmware'" :class="['firmware-grid', { focused: fStep > 0 || selectedFirmware }]" ><div><ElCard class="firmware-panel"><div class="firmware-toolbar"><label>搜索名称 / 版本<input aria-label="搜索固件" v-model="fDraftFilter.keyword"></label><label>租户<select aria-label="固件租户" v-model="fDraftFilter.tenantId" :disabled="role !== 'platformAdmin'"><option v-for="item in tenants" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>产品<select aria-label="固件产品" :value="fDraftFilter.productId ?? ''" @change="fDraftFilter.productId = ($event.target as HTMLSelectElement).value || undefined"><option value="">全部产品</option><option v-for="(name, id) in productNames" :key="id" :value="id">{{ name }}</option></select></label><label>状态<select aria-label="固件状态" :value="fDraftFilter.status ?? ''" @change="fDraftFilter.status = (($event.target as HTMLSelectElement).value || undefined) as Firmware['status'] | undefined"><option value="">全部状态</option><option v-for="(name, id) in firmwareStatus" :key="id" :value="id">{{ name }}</option></select></label><ElButton type="primary" @click="fFilter = { ...fDraftFilter, page: 1 }">查询</ElButton><ElButton v-if="canManage" type="primary" @click="newFirmware">新建固件</ElButton></div></ElCard>
<ElCard class="firmware-panel"><h2>固件列表 · 共 {{ fTotal }} 条</h2><div class="firmware-table"><table><thead><tr><th>名称</th><th>产品</th><th>版本</th><th>大小</th><th>SHA-256</th><th>状态</th><th>创建人</th><th>创建时间</th></tr></thead><tbody><tr v-for="row in fRows" :key="row.id"><td><button @click="openFirmware(row.id)">{{ row.name }}</button></td><td>{{ productNames[row.productId] }}</td><td>{{ row.version }}</td><td>{{ (row.sizeBytes / 1024 / 1024).toFixed(1) }} MiB</td><td class="firmware-hash" :title="row.checksum">{{ row.checksum.slice(0, 8) }}…</td><td>{{ firmwareStatus[row.status] }}</td><td>{{ row.createdBy }}</td><td>{{ displayTime(row.createdAt) }}</td></tr></tbody></table><p v-if="!fRows.length">当前条件没有固件。</p></div><div class="firmware-actions"><ElButton :disabled="fFilter.page <= 1" @click="fFilter = { ...fFilter, page: fFilter.page - 1 }">上一页</ElButton><span>{{ fFilter.page }} / {{ Math.max(1, Math.ceil(fTotal / fFilter.pageSize)) }}</span><ElButton :disabled="fFilter.page * fFilter.pageSize >= fTotal" @click="fFilter = { ...fFilter, page: fFilter.page + 1 }">下一页</ElButton></div></ElCard></div>
<div><ElCard v-if="fStep > 0" class="firmware-panel"><h2>新建固件</h2><ol class="firmware-steps"><li v-for="(name, index) in ['选择文件', '确认元数据与校验', '适配产品与提交']" :key="name" :class="{ active: fStep === index + 1 }">{{ index + 1 }}. {{ name }}</li></ol>
<div v-if="fStep === 1" class="firmware-form"><label class="wide">本地固件文件<input aria-label="本地固件文件" type="file" accept=".bin,.hex,.ota" @change="selectFile"></label><p class="wide">仅在浏览器读取文件并计算 SHA-256；不上传或保存二进制内容。允许 .bin、.hex、.ota，最大 64 MiB。</p><p role="status">{{ fileState === 'reading' ? fileProgress < 100 ? `正在读取文件 ${fileProgress}%` : '正在计算 SHA-256…' : fileInfo ? `${fileInfo.fileName} · ${(fileInfo.sizeBytes / 1024).toFixed(1)} KiB · 校验完成` : '请选择文件' }}</p><progress v-if="fileState === 'reading'" class="wide" aria-label="固件文件读取进度" max="100" :value="fileProgress"></progress><div class="firmware-actions wide"><ElButton @click="cancelFile">取消</ElButton><ElButton type="primary" :disabled="!fileInfo || fileState === 'reading'" @click="fStep = 2">下一步</ElButton></div></div>
<div v-if="fStep === 2" class="firmware-form"><p class="firmware-hash wide">SHA-256：{{ fileInfo?.checksum }}</p><label>固件名称<input aria-label="固件名称" v-model="fInput.name"></label><label>版本号<input aria-label="固件版本号" v-model="fInput.version" placeholder="2.5.0"></label><label class="wide">发布说明<textarea aria-label="发布说明" maxlength="500" v-model="fInput.description"></textarea></label><div class="firmware-actions wide"><ElButton @click="fStep = 1">上一步</ElButton><ElButton type="primary" :disabled="!fInput.name.trim() || !fInput.version.trim()" @click="fStep = 3">下一步</ElButton></div></div>
<div v-if="fStep === 3" class="firmware-form"><label>租户<select aria-label="新建固件租户" :value="fInput.tenantId" :disabled="role !== 'platformAdmin'" @change="setNewTenant(($event.target as HTMLSelectElement).value)"><option value="ten_202609_001">华东智联</option><option value="ten_202609_002">全球能源</option></select></label><label>所属产品<select aria-label="固件所属产品" :value="fInput.productId" @change="fInput.productId = ($event.target as HTMLSelectElement).value; fInput.compatibleProductIds = [fInput.productId]"><option :value="fInput.tenantId === 'ten_202609_002' ? 'prod_as_002' : 'prod_as_001'">{{ productNames[fInput.productId] }}</option></select></label><p class="firmware-note wide">适配产品：{{ fInput.compatibleProductIds.map(id => productNames[id]).join('、') }}。提交后为草稿，需验证再发布。</p><p class="firmware-note wide" role="status">{{ storageNote }}</p><div class="firmware-actions wide"><ElButton @click="fStep = 2">上一步</ElButton><ElButton type="primary" @click="saveFirmware">登记固件元数据</ElButton></div></div></ElCard>
<ElCard v-else-if="selectedFirmware" class="firmware-panel"><div class="firmware-controls"><h2>{{ selectedFirmware.name }} · {{ selectedFirmware.version }}</h2><ElButton @click="selectedFirmware = null">关闭</ElButton></div><p>{{ firmwareStatus[selectedFirmware.status] }} · {{ productNames[selectedFirmware.productId] }} · {{ selectedFirmware.fileName }}</p><p>{{ selectedFirmware.description }}</p><p class="firmware-hash">SHA-256：{{ selectedFirmware.checksum }}</p><p>校验结果：{{ selectedFirmware.checksumValid ? '通过' : '失败' }} · 适配：{{ selectedFirmware.compatibleProductIds.map(id => productNames[id]).join('、') }}</p><h3>同产品版本比较</h3><div class="firmware-table"><table class="firmware-compare"><thead><tr><th>版本</th><th>状态</th><th>文件大小</th><th>SHA-256</th><th>适配产品</th><th>说明</th></tr></thead><tbody><tr v-for="row in versionPeers" :key="row.id"><td>{{ row.version }}{{ row.id === selectedFirmware.id ? '（当前）' : '' }}</td><td>{{ firmwareStatus[row.status] }}</td><td>{{ (row.sizeBytes / 1024 / 1024).toFixed(1) }} MiB</td><td class="firmware-hash" :title="row.checksum">{{ row.checksum.slice(0, 12) }}…</td><td>{{ row.compatibleProductIds.map(id => productNames[id]).join('、') }}</td><td>{{ row.description || '—' }}</td></tr></tbody></table></div><h3>引用任务</h3><p v-for="id in selectedFirmware.referencedTaskIds" :key="id"><a :href="`/firmware?tab=ota&task=${encodeURIComponent(id)}`">{{ id }}</a></p><p v-if="!selectedFirmware.referencedTaskIds.length">尚无 OTA 任务引用。</p><div class="firmware-actions"><ElButton v-if="canManage && selectedFirmware.status === 'draft'" @click="confirm = { action: 'verify' }">验证</ElButton><ElButton v-if="canManage && selectedFirmware.status === 'verified'" type="primary" @click="confirm = { action: 'release' }">发布</ElButton><ElButton v-if="canManage && selectedFirmware.status === 'released'" @click="confirm = { action: 'archive' }">归档</ElButton><ElButton v-if="canManage && selectedFirmware.status !== 'released'" @click="confirm = { action: 'remove' }">删除元数据</ElButton></div><h3>操作历史</h3><ol><li v-for="(entry, index) in selectedFirmware.history" :key="index">{{ displayTime(entry.at) }} · {{ entry.actorId }} · {{ entry.detail }}</li></ol></ElCard>
<ElCard v-else class="firmware-panel"><h2>固件详情</h2><p>从列表选择一个版本，查看校验、适配、引用任务和操作历史。</p></ElCard></div></div>
<div v-if="tab === 'ota'" :class="['firmware-grid', { focused: oStep > 0 || task }]" ><div><ElCard class="ota-panel"><div class="firmware-toolbar"><label>租户<select aria-label="OTA 租户" v-model="oDraftFilter.tenantId" :disabled="role !== 'platformAdmin'"><option v-for="item in tenants" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>状态<select aria-label="OTA 状态" :value="oDraftFilter.status ?? ''" @change="oDraftFilter.status = (($event.target as HTMLSelectElement).value || undefined) as OtaTask['status'] | undefined"><option value="">全部状态</option><option v-for="(name, id) in taskStatus" :key="id" :value="id">{{ name }}</option></select></label><ElButton type="primary" @click="oFilter = { ...oDraftFilter, page: 1 }">查询</ElButton><ElButton v-if="canManage" type="primary" @click="newOta">创建 OTA 任务</ElButton></div></ElCard><ElCard class="ota-panel"><h2>OTA 任务 · 共 {{ oTotal }} 条</h2><div class="firmware-table"><table><thead><tr><th>任务</th><th>固件</th><th>目标</th><th>批次</th><th>状态</th><th>更新时间</th></tr></thead><tbody><tr v-for="row in oRows" :key="row.id"><td><button @click="openTask(row.id)">{{ row.id }}</button></td><td>{{ row.firmwareId }}</td><td>{{ row.targetSelector.deviceIds.length }} 台</td><td>{{ row.currentBatch < 0 ? '未开始' : `${row.currentBatch + 1}/${row.batches.length}` }}</td><td>{{ taskStatus[row.status] }}</td><td>{{ displayTime(row.updatedAt) }}</td></tr></tbody></table><p v-if="!oRows.length">当前条件没有 OTA 任务。</p></div><div class="firmware-actions"><ElButton :disabled="oFilter.page <= 1" @click="oFilter = { ...oFilter, page: oFilter.page - 1 }">上一页</ElButton><span>{{ oFilter.page }} / {{ Math.max(1, Math.ceil(oTotal / oFilter.pageSize)) }}</span><ElButton :disabled="oFilter.page * oFilter.pageSize >= oTotal" @click="oFilter = { ...oFilter, page: oFilter.page + 1 }">下一页</ElButton></div></ElCard></div>
<div><ElCard v-if="oStep > 0" class="ota-panel"><h2>创建 OTA 任务</h2><ol class="firmware-steps"><li v-for="(name, index) in ['选择固件', '选择目标设备', '灰度配置', '影响预览', '确认创建']" :key="name" :class="{ active: oStep === index + 1 }">{{ index + 1 }}. {{ name }}</li></ol>
<div v-if="oStep === 1" class="ota-form"><label>租户<select aria-label="新建 OTA 租户" :value="oInput.tenantId" :disabled="role !== 'platformAdmin'" @change="setOtaTenant(($event.target as HTMLSelectElement).value)"><option value="ten_202609_001">华东智联</option><option value="ten_202609_002">全球能源</option></select></label><label>已发布固件<select aria-label="OTA 固件" :value="oInput.firmwareId" @change="chooseFirmware(($event.target as HTMLSelectElement).value)"><option value="">请选择</option><option v-for="row in options" :key="row.id" :value="row.id">{{ row.name }} · {{ row.version }} · {{ productNames[row.productId] }}</option></select></label><p class="wide">仅显示已校验且已发布的固件；校验失败、草稿和归档版本不可选。</p><div class="firmware-actions wide"><ElButton @click="oStep = 0">取消</ElButton><ElButton type="primary" :disabled="!oInput.firmwareId" @click="oStep = 2">下一步</ElButton></div></div>
<div v-if="oStep === 2" class="ota-form"><p class="wide">产品：{{ productNames[oInput.productId] }}。选择设备或标签，离线设备会在预览中标明并于执行时失败。</p><div class="ota-devices wide"><label v-for="device in targets" :key="device.id"><input type="checkbox" :checked="oInput.targetSelector.deviceIds.includes(device.id)" @change="target(device.id, ($event.target as HTMLInputElement).checked)">{{ device.name }} · {{ device.status }}</label></div><label class="wide">标签（可选，逗号分隔）<input aria-label="目标标签" :value="oInput.targetSelector.tags.join(',')" @input="setOtaTags(($event.target as HTMLInputElement).value)"></label><div class="firmware-actions wide"><ElButton @click="oStep = 1">上一步</ElButton><ElButton type="primary" @click="oStep = 3">下一步</ElButton></div></div>
<div v-if="oStep === 3" class="ota-form"><label>灰度批次（%）<input aria-label="灰度批次" :value="oInput.batches.join(',')" @input="oInput.batches = ($event.target as HTMLInputElement).value.split(',').map(Number)"></label><label>失败阈值（%）<input aria-label="失败阈值" type="number" min="0" max="100" :value="oInput.failureThreshold * 100" @input="oInput.failureThreshold = Number(($event.target as HTMLInputElement).value) / 100"></label><label class="wide">模拟失败设备<select aria-label="模拟失败设备" :value="Object.keys(oInput.failureModes)[0] ?? ''" @change="setFailureDevice(($event.target as HTMLSelectElement).value)"><option value="">无</option><option v-for="device in targets.filter(item => oInput.targetSelector.deviceIds.includes(item.id))" :key="device.id" :value="device.id">{{ device.name }}</option></select></label><label v-if="Object.keys(oInput.failureModes).length">失败阶段<select aria-label="模拟失败阶段" :value="Object.values(oInput.failureModes)[0]" @change="setFailureMode(($event.target as HTMLSelectElement).value as FailureMode)"><option value="download">下载失败</option><option value="checksum">校验失败</option><option value="reboot">重启超时</option></select></label><p class="wide">批次百分比须合计 100；失败率超过阈值时自动暂停并生成模拟告警。</p><div class="firmware-actions wide"><ElButton @click="oStep = 2">上一步</ElButton><ElButton type="primary" @click="previewOta">影响预览</ElButton></div></div>
<div v-if="oStep === 4 && preview"><div class="ota-stats"><div><span>目标设备</span><strong>{{ preview.total }}</strong></div><div><span>离线或不可升级</span><strong>{{ preview.offline }}</strong></div><div><span>失败阈值</span><strong>{{ (preview.failureThreshold * 100).toFixed(0) }}%</strong></div></div><p>批次：{{ preview.batchCounts.map((count, index) => `第 ${index + 1} 批 ${count} 台`).join(' · ') }}</p><ul><li v-for="device in preview.devices" :key="device.id">{{ device.name }} · 当前 {{ device.currentVersion }} · {{ device.compatible ? '可升级' : device.reason }}</li></ul><div class="firmware-actions"><ElButton @click="oStep = 3">上一步</ElButton><ElButton type="primary" @click="oStep = 5">下一步</ElButton></div></div>
<div v-if="oStep === 5 && preview"><p class="firmware-note">确认创建 OTA 草稿：{{ preview.total }} 台设备，{{ oInput.batches.length }} 个灰度批次；超过 {{ (oInput.failureThreshold * 100).toFixed(0) }}% 失败率会暂停。所有进度仅为浏览器 Mock。</p><div class="firmware-actions"><ElButton @click="oStep = 4">上一步</ElButton><ElButton type="primary" @click="createOta">确认创建</ElButton></div></div></ElCard>
<ElCard v-else-if="task" class="ota-panel"><div class="firmware-controls"><h2>{{ task.id }} · {{ taskStatus[task.status] }}</h2><ElButton @click="task = null">关闭</ElButton></div><p>{{ task.kind === 'rollback' ? `回滚任务 · 来源 ${task.sourceTaskId}` : '升级任务' }} · 固件 {{ task.firmwareId }} · 目标 {{ task.targetSelector.deviceIds.length }} 台 · 批次 {{ task.currentBatch < 0 ? '未开始' : `${task.currentBatch + 1}/${task.batches.length}` }}</p><p v-if="task.status === 'paused' && task.alarmCreated" class="ota-alert" role="alert">失败率已超过阈值，系统自动暂停 OTA 并创建模拟告警。需人工确认后继续。</p><p v-if="!connected" class="ota-alert" role="status">事件连接已断开；数据可能过期。<ElButton @click="openTask(task.id)">重新连接</ElButton></p><p v-if="(task.status === 'draft' || task.status === 'paused') && canOperate" class="ota-capacity-note" role="status">{{ capacityNote }}</p><div class="ota-controls"><ElButton v-if="canManage && task.status === 'draft'" type="primary" @click="confirm = { action: 'start' }">开始</ElButton><ElButton v-if="canOperate && !finished(task.status)" @click="confirm = { action: 'pause' }">暂停</ElButton><ElButton v-if="canOperate && task.status === 'paused'" @click="confirm = { action: 'resume' }">继续</ElButton><ElButton v-if="canManage && !['cancelled', 'succeeded', 'failed', 'rolledBack'].includes(task.status)" @click="confirm = { action: 'cancel' }">取消</ElButton><ElButton v-if="canManage && task.kind === 'upgrade' && ['paused', 'failed', 'succeeded'].includes(task.status) && done > 0" @click="confirm = { action: 'rollback' }">回滚</ElButton><ElButton v-if="canOperate && !finished(task.status)" @click="connected = false; message = '已断开自动事件连接；可手动推进或重连'">断开事件</ElButton><ElButton v-if="canOperate && !finished(task.status)" @click="manualAdvance">推进模拟事件</ElButton></div><div class="ota-stats"><div>总体进度<strong>{{ progress }}%</strong></div><div>成功<strong>{{ done }}</strong></div><div>失败<strong>{{ failed }}</strong></div><div>失败率<strong>{{ latest.length ? (failed / latest.length * 100).toFixed(1) : '0' }}%</strong></div></div><h3>状态分布与进度趋势</h3><div class="ota-trend" role="img" :aria-label="`${done} 台成功，${failed} 台失败，${task.targetSelector.deviceIds.length - done - failed} 台待处理`"><span :style="{ width: `${done / task.targetSelector.deviceIds.length * 100}%`, background: '#29b783' }"></span><span :style="{ width: `${failed / task.targetSelector.deviceIds.length * 100}%`, background: '#d46360' }"></span></div><section aria-label="版本分布" class="ota-version-distribution"><h4>当前模拟版本分布</h4><ul><li v-for="item in otaVersionDistribution(task)" :key="item.version">{{ item.version }}：{{ item.count }} 台</li></ul></section><h4>设备进度历史</h4><template v-if="taskTrend.length > 1"><svg class="ota-history-svg" viewBox="0 0 100 40" preserveAspectRatio="none" role="img" aria-label="OTA 历史进度：绿色为成功设备数，红色为失败设备数，灰色为已取消设备数"><path :d="otaTrendPath(taskTrend, 'succeeded')" class="ota-history-success" /><path :d="otaTrendPath(taskTrend, 'failed')" class="ota-history-failed" /><path :d="otaTrendPath(taskTrend, 'cancelled')" class="ota-history-cancelled" /></svg><details><summary>查看历史进度数据 · {{ taskTrend.length }} 个时间点</summary><table><thead><tr><th>时间</th><th>成功</th><th>失败</th><th>待处理</th><th>已取消</th></tr></thead><tbody><tr v-for="(point, index) in taskTrend" :key="`${point.at}-${index}`"><td>{{ displayTime(point.at) }}</td><td>{{ point.succeeded }}</td><td>{{ point.failed }}</td><td>{{ point.pending }}</td><td>{{ point.cancelled }}</td></tr></tbody></table></details></template><p v-else>任务尚无设备进度事件。</p><ul class="ota-batches"><li v-for="(percent, index) in task.batches" :key="index">第 {{ index + 1 }} 批 · {{ percent }}% · {{ index < task.currentBatch ? '已完成' : index === task.currentBatch ? task.status === 'paused' ? '已暂停' : '进行中' : '待开始' }}</li></ul><h3>设备明细</h3><div class="firmware-toolbar"><label>状态<select aria-label="设备执行状态" v-model="deviceFilter"><option value="all">全部</option><option value="failed">失败</option><option value="succeeded">成功</option></select></label><label>失败原因<input aria-label="失败原因搜索" v-model="reasonFilter"></label></div><div class="firmware-table"><table><thead><tr><th>设备</th><th>批次</th><th>尝试</th><th>阶段</th><th>版本</th><th>失败原因</th><th>操作</th></tr></thead><tbody><tr v-for="item in filteredExecutions" :key="item.id"><td><a :href="`/devices?device=${encodeURIComponent(item.deviceId)}`">{{ item.deviceId }}</a></td><td>{{ item.batch + 1 }}</td><td>{{ item.attempt }}</td><td>{{ taskStatus[item.status] }}</td><td>{{ item.fromVersion }} → {{ item.toVersion }}</td><td>{{ item.reason ?? '—' }}</td><td><ElButton v-if="canOperate && item.status === 'failed' && !task.executions.some(other => other.deviceId === item.deviceId && other.attempt > item.attempt)" @click="confirm = { action: 'retry', deviceId: item.deviceId }">重试</ElButton></td></tr></tbody></table><p v-if="!filteredExecutions.length">当前筛选没有设备执行记录。</p></div><h3>操作日志</h3><ol class="ota-log"><li v-for="event in task.events" :key="event.id">{{ displayTime(event.at) }} · {{ event.detail }}</li></ol></ElCard>
<ElCard v-else class="ota-panel"><h2>任务详情</h2><p>从列表选择任务，查看批次、设备进度、失败原因和操作日志。</p></ElCard></div></div>
</main><div v-if="confirm" class="ota-confirm-backdrop"><div class="ota-confirm" role="dialog" aria-modal="true" aria-label="风险操作确认"><h2>确认{{ confirm.action === 'rollback' ? '回滚' : confirm.action === 'retry' ? '重试' : confirm.action === 'cancel' ? '取消任务' : '操作' }}</h2><p>{{ confirmationText }}</p><div class="firmware-actions"><ElButton type="primary" @click="runAction">确认</ElButton><ElButton @click="confirm = null">返回</ElButton></div></div></div></div>
</template>
